"""Retain dependency notices outside the help PDF."""

import argparse
import hashlib
import json
import subprocess
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent


def lock_hash():
    return hashlib.sha256((ROOT / "Cargo.lock").read_bytes()).hexdigest()


def write_notices(document):
    sections = [
        "Vpdf dependency notices",
        "Cargo.lock SHA-256: " + lock_hash(),
        "Generated by cargo-about 0.9.3; all workspace features and targets.",
        "Optional dependencies may not appear in every build.",
    ]
    for license in document["licenses"]:
        used = sorted(
            (row["crate"] for row in license["used_by"]),
            key=lambda package: (package["name"], package["version"]),
        )
        sections.append(license["name"] + " (" + license["id"] + ")")
        for package in used:
            sections.append(
                package["name"]
                + " "
                + package["version"]
                + "\n"
                + ", ".join(package["authors"])
                + "\n"
                + (
                    package["repository"]
                    or "https://crates.io/crates/" + package["name"]
                )
            )
        sections.append(license["text"])
    (ROOT / "docs/licenses/dependencies.txt").write_text(
        "\n\n".join(sections) + "\n"
    )
    metadata = json.loads(
        subprocess.check_output(
            ["cargo", "metadata", "--locked", "--format-version", "1"],
            cwd=ROOT,
            text=True,
        )
    )
    package = next(
        package
        for package in metadata["packages"]
        if package["name"] == "mupdf-sys"
    )
    native = Path(package["manifest_path"]).parent / "mupdf"
    files = {
        "COPYING",
        "README",
        "thirdparty/libjpeg/README",
        "thirdparty/freetype/docs/FTL.TXT",
    }
    for folder in [native / "thirdparty", native / "resources/fonts"]:
        for path in folder.rglob("*"):
            if path.is_file() and path.name.lower().startswith(
                ("copying", "license", "licence", "notice", "copyright")
            ):
                files.add(path.relative_to(native).as_posix())
    sections = [
        "MuPDF and bundled third-party notices",
        "Cargo.lock SHA-256: " + lock_hash(),
        "Source: " + package["source"],
        "Inventory includes optional bundled components.",
    ]
    for name in sorted(files):
        path = native / name
        if path.is_file():
            sections.extend([name, path.read_text(errors="replace")])
    (ROOT / "docs/licenses/native.txt").write_text("\n\n".join(sections) + "\n")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    parser.add_argument("--json", type=Path)
    args = parser.parse_args()
    if args.check:
        for name in ["dependencies.txt", "native.txt"]:
            text = (ROOT / "docs/licenses" / name).read_text()
            if "Cargo.lock SHA-256: " + lock_hash() not in text:
                raise ValueError("Dependency notices differ from lockfile")
        return
    if args.json:
        document = json.loads(args.json.read_bytes())
    else:
        version = subprocess.check_output(
            ["cargo-about", "--version"], text=True
        ).strip()
        if version != "cargo-about 0.9.3":
            raise ValueError("Notice generator differs from pin")
        document = json.loads(
            subprocess.check_output(
                [
                    "cargo-about",
                    "generate",
                    "--workspace",
                    "--locked",
                    "--all-features",
                    "--format",
                    "json",
                    "-c",
                    "scripts/licenses/about.toml",
                ],
                cwd=ROOT,
                text=True,
                timeout=300,
            )
        )
    write_notices(document)


if __name__ == "__main__":
    main()
